"""Evolve the existing single AA overview. Preserve historical evidence."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];project=R.parent.parent
page=project/'project-overview.html';d=json.loads((R/'results/cfd-summary.json').read_text())
rel='Airflow-Assessment/pass-by-study/'
def a(file,label):return f'<a href="{rel+file}">{label}</a>'
rows=''
for r in d['cases']:
    p=r['reference'];rows+=f'<tr><td>{r["case"]}<br><small>{r["layout"]}; {r["width_m"]*1000:g}×{r["height_m"]*1000:g}mm</small></td><td>{r["distance_m"]*100:g}cm / {r["reference_patch"]}</td><td>{p["peak_area_deficit_k"]:.2f}K</td><td>{p["time_above_delta6_s"]:.3f}s / {p["longest_continuous_above_delta6_s"]:.3f}s</td><td>{r["source_c"]:.2f}°C / {r["wind_m_s"]:g}m/s</td><td>{r["duration_s"]:g}s</td><td>{"pass" if r["numerical_screens_pass"] else "FAIL"}</td></tr>'
demo='R00_wide_d35' if any(r['case']=='R00_wide_d35' for r in d['cases']) else 'P00_one_d20'
video=''
if (R/'results'/f'{demo}-air-exposure.mp4').exists():video=f'<video style="width:100%;max-height:690px" controls preload="metadata" poster="{rel}results/{demo}-air-field.png"><source src="{rel}results/{demo}-air-exposure.mp4" type="video/mp4"></video><p class="sub">{demo}: actual transient CFD with a virtual moving air square. No human body. Display interpolates1s native fields; the temperature trace uses about25ms probes. No synthetic turbulent motion.</p>'
options=''.join(f'<option value="{r["case"]}">{r["case"]}</option>' for r in d['cases'])
refinement=''
if (R/'results/refinement-comparison.png').exists():refinement=f'<h3>One nozzle geometry iteration</h3><p>Change140×80mm to280×40mm, with the same total outlet area and air mass. Wider coverage along the path can trade against vertical coverage and mixing. Two-grid and opposing-wind checks stay separate. This is a manual design comparison, not a global optimizer.</p><img style="width:100%" src="{rel}results/refinement-comparison.png" alt="Nozzle refinement, two-grid and wind comparisons">'
if (R/'results/row-comparison.png').exists():refinement+=f'<h3>Along-path outlet row</h3><p>Four outlets at one height trade vertical coverage for additional encounters along the walking direction. The8°C source case is a heat-pickup sensitivity at the same air mass.</p><img style="width:100%" src="{rel}results/row-comparison.png" alt="Along-path row exposure and warmer source comparison">'
if (R/'results/pitch-comparison.png').exists():refinement+=f'<h3>Aim compensates for falling cold air</h3><p>The horizontal50cm control retains cold air below the target height. An8° upward prescribed-flow test checks retargeting. This uses oblique velocity on a vertical slot patch, not resolved tilted-CAD faces; actual inlet mass is checked.</p><img style="width:100%" src="{rel}results/pitch-comparison.png" alt="Native CFD compares horizontal and upward aim at50cm">'
block=f'''<!-- pass-by-results-start -->
<section id="pass-by-results" style="scroll-margin-top:180px"><div class="eyebrow">Executed open-air CFD reach screen · 21 Oct 2026</div><h2>Outdoor nozzles: air exposure while walking past</h2>
<div class="warn"><strong>Moving air probes, not a moving person.</strong> This stage contains no human body, wake, skin heat transfer or enclosure. It screens whether prescribed cold jets can deliver a local air-temperature deficit. It does not establish personal cooling or comfort. The old seated-enclosure results remain retired.</div>
<p><span class="status">{d['controls_completed']} of9 layout controls recorded</span> <span class="status">{len(d['cases'])} thermal cases recorded</span> <span class="status">57 Lean axiom checks pass</span> <span class="status pending">Source state conditional</span> <span class="status pending">No human body in this stage</span></p>
<p>Confirmed:20–50cm nominal nearest-target range; valve open at most30s while people walk past. Assumed walking speed1.2m/s, with0.6/1.8m/s sensitivity. All controls use four140×80mm slot faces and the same77.6g/s source, nominally0.96°C at30°C ambient. A source/collector/line transient has not been simulated.</p>
<img style="width:100%;max-height:720px;object-fit:contain" src="{rel}results/outdoor-layouts.png" alt="One-sided, two-sided and overhead outdoor nozzle layouts without an enclosure">
<h3>Inspect a completed case</h3><label for="aa-passby-case">Case </label><select id="aa-passby-case" style="max-width:100%;font:inherit;padding:8px">{options}</select><div id="aa-passby-case-detail" aria-live="polite"></div>
{video}
<h3>Common reference passage</h3><p>1.2m/s; centre crosses at5s after ideal nozzle activation; path x=-0.8..0.8m. The target is a moving5×5cm air square. Side reference is y=-0.2m,z=1.15m; overhead reference is z=1.75m,y=0. These differ in body region. The case audits retain all five air patches and all simulated arrival/speed combinations.</p>
<div class="scroll"><table><tr><th>Case / outlet</th><th>Nominal distance / patch</th><th>Peak deficit</th><th>Total / longest time &gt;6K</th><th>Supply / wind</th><th>Solver duration</th><th>Numerical screens</th></tr>{rows}</table></div>
<img style="width:100%" src="{rel}results/layout-comparison.png" alt="CFD air exposure and peak deficit versus nominal distance"><details><summary>All control passage traces</summary><img style="width:100%" src="{rel}results/passage-traces.png" alt="Moving-square air-temperature deficit through the nine controls"></details>
{refinement}
<h3>CAD prototypes</h3><img style="width:100%;max-height:680px;object-fit:contain" src="{rel}results/outdoor-nozzle-assembly.png" alt="Actual generated nozzle CAD beside a walking path; upright reference envelope absent from CFD">
<p>100mm nominal slip spigot;95.2mm clear inlet;205mm length;2.4mm nominal wall. Both meshes are watertight, consistently oriented and one component. Bambu H2S / PLA /0.4mm: start0.2mm layers and4–6 walls; inspect supports and fit. No stock hose/clamp connection, stand or motor interface is fitted. Near-atmospheric exhaust only. External CFD shares outlet dimensions; it does not resolve the actual internal CAD loft.</p>
<p>{a('cad/outlet-140x80-print-mm.stl','140×80 STL, mm')} · {a('cad/outlet-140x80-metres.step','140×80 STEP, metres')} · {a('cad/outlet-280x40-print-mm.stl','280×40 STL, mm')} · {a('cad/outlet-280x40-metres.step','280×40 STEP, metres')}</p>
<h3>What remains unresolved</h3><p>Actual motor/load thermal state and balanced commercial cold-air distribution; detection/valve/line startup; moving upright body and wake; skin heat transfer versus ambient; source, wind, grid, domain and turbulence uncertainty; required minimum exposure per person. A6K air deficit does not by itself demonstrate useful personal cooling. No globally optimal layout is established.</p>
<p>{a('FIRST-PRINCIPLES.txt','Editable first-principles formulation')} · <a href="Airflow-Assessment/formal-model/AAThermo/PassBy.lean">Pass-by Lean proofs</a> · <a href="Airflow-Assessment/formal-model/proof-verification.json">Lean build and axiom checks</a> · {a('results/cfd-summary.json','All CFD results')} · {a('scripts/open_flow.py','Solver and mesh source')} · {a('output/pdf/AA-outdoor-pass-by-screen.pdf','Engineering report PDF')} · <a href="Airflow-Assessment/AA-outdoor-pass-by-study.zip">Reproducibility package</a></p>
<script id="aaPassByCFDData" type="application/json">{json.dumps(d,separators=(',',':'))}</script><script>(()=>{{const data=JSON.parse(document.getElementById('aaPassByCFDData').textContent),selector=document.getElementById('aa-passby-case'),target=document.getElementById('aa-passby-case-detail');function select(name){{const r=data.cases.find(x=>x.case===name);if(!r)return;selector.value=name;const p=r.reference;target.innerHTML='<p><strong>'+p.peak_area_deficit_k.toFixed(2)+'K peak air-area deficit</strong> · '+p.time_above_delta6_s.toFixed(3)+'s total / '+p.longest_continuous_above_delta6_s.toFixed(3)+'s continuous above6K · '+p.positive_deficit_dose_k_s.toFixed(2)+'K s air-exposure dose.</p><p>Patch '+r.reference_patch+'; '+r.distance_m*100+'cm nominal clearance; '+r.duration_s+'s CFD; '+r.source_c.toFixed(2)+'°C supply; '+r.wind_m_s+'m/s wind; '+r.cells.toLocaleString()+' cells. No body or skin temperature.</p><p><a href="{rel}cfd/cases/'+r.case+'/audit.json">Native-field audit and all moving patches</a> · <a href="{rel}cfd/cases/'+r.case+'/moving-probe-traces.json">Temperature/velocity traces</a></p>';target.innerHTML+='<p class="sub">Hypothetical upward temperature-error allowances: '+Object.entries(p.assumed_upward_temperature_error_k_sensitivity).map(([e,v])=>e+'K → '+v.total_s.toFixed(3)+'s above6K').join('; ')+'. These are not established physical error bounds.</p>';return r;}}selector.addEventListener('change',()=>select(selector.value));window.aaPassByCFD={{data,select}};select('{demo}');}})();</script>
</section><!-- pass-by-results-end -->'''
s=page.read_text()
if '<!-- pass-by-results-start -->' in s:
    begin=s.index('<!-- pass-by-results-start -->');end=s.index('<!-- pass-by-results-end -->',begin)+len('<!-- pass-by-results-end -->');s=s[:begin]+s[end:]
idx=s.index('<section id="pass-by-scope"');s=s[:idx]+block+'\n'+s[idx:]
if 'href="#pass-by-results"' not in s:s=s.replace('<nav aria-label="Sections">','<nav aria-label="Sections"><a href="#pass-by-results">Outdoor CFD results</a>',1)
s=s.replace('Open-jet CFD running · body absent','Open-jet results above · body absent').replace('The nine open-jet simulations are running.','The recorded open-jet results are above; see the completed control count.')
page.write_text(s);print(page)
